INSERT INTO `wa_notification` (`cnfg_id`, `cnfg_token`, `cnfg_sender`, `cnfg_intro`, `cnfg_status`, `cnfg_kbm`, `cnfg_eskul`, `cnfg_kegiatan`, `cnfg_intro_kbm`, `cnfg_intro_eskul`, `cnfg_intro_kegiatan`, `cnfg_template_izin`, `cnfg_template_sakit`, `cnfg_template_guru_izin`, `cnfg_no_kepsek`) VALUES
(1, 'OBWpwEWJuVt1RmqNN8YftRIlEWmXuK01', '6289653958911', 'Yth. Wali murid *{nama_siswa}*\r\n\r\nMenginformasikan bahwa {nama_siswa} baru saja melaksanakan *{tipe_presensi}*, tepatnya pukul *{waktu}* dengan status presensi adalah *{status_presensi}*. {ket_tambahan}', 1, 1, 1, 1, '===============\r\n*NOTIFIKASI PRESENSI*\r\n===============\r\nDengan hormat, \r\nBerikut kami informasikan data rekam presensi kehadiran di sekolah atas nama:\r\n\r\n==============\r\n *INFORMASI PRESENSI*\r\n==============\r\nNama: *{nama_siswa}*\r\nJenis Presensi: *{tipe_presensi}*\r\nWaktu Presensi: *{waktu}*\r\nStatus Kehadiran: *{status_presensi}*\r\nKeterangan: {ket_tambahan}\r\n==============', '???????????????????????????\r\n? *NOTIFIKASI KEGIATAN EKSTRAKURIKULER*\r\n???????????????????????????\r\n\r\nYth. Bapak/Ibu Orang Tua/Wali,\r\n\r\nDengan hormat kami sampaikan bahwa putra/putri Bapak/Ibu telah melakukan presensi untuk kegiatan ekstrakurikuler sekolah.\r\n\r\n???????????????????\r\n? *INFORMASI PRESENSI ESKUL*\r\n???????????????????\r\n\r\n? Nama Siswa: *{nama_siswa}*\r\n? Jenis Presensi: *{tipe_presensi}*\r\n? Waktu Presensi: *{waktu}*\r\n? Status Kehadiran: *{status_presensi}*\r\n? Jadwal Eskul: {ket_tambahan}', '???????????????????????????\r\n? *NOTIFIKASI KEGIATAN SEKOLAH*\r\n???????????????????????????\r\nYth. Bapak/Ibu Orang Tua/Wali,\r\nDengan hormat kami informasikan bahwa putra/putri Bapak/Ibu telah melakukan presensi kehadiran pada kegiatan sekolah yang sedang berlangsung.\r\n???????????????????\r\n? *INFORMASI KEGIATAN*\r\n???????????????????\r\n? Nama Siswa: *{nama_siswa}*\r\n? Jenis Presensi: *{tipe_presensi}*\r\n? Waktu Presensi: *{waktu}*\r\n? Status Kehadiran: *{status_presensi}*\r\n? Detail Kegiatan: {ket_tambahan}', '', 'Yth. Wali Kelas, diberitahukan {nama_siswa} kelas {kelas} {tipe} pada {tanggal}. Alasan: {alasan}. Mohon maklum.', '', '6282210103115');

